command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="e70d3ec5c91118acd113f2d90cb6a37f1c7c4ac8";$candidate="239dc91c244c0c48d0afe097c84e42ecb0ddd123";$branch="work/unc-network-shell-visuals-20261007"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "network visual BitBlt baseline fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before network visual BitBlt baseline"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "network visual BitBlt candidate moved"}
$temp=Join-Path $env:RUNNER_TEMP ("fly-network-visual-bitblt-"+$env:GITHUB_RUN_ID)
if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
try{
 & git worktree add --detach $temp $candidate
 if($LASTEXITCODE -ne 0){throw "network visual BitBlt worktree add failed"}
 Set-Location -LiteralPath $temp
 & git diff --check ($main+"..."+$candidate)
 if($LASTEXITCODE -ne 0){throw "network visual BitBlt diff check failed"}
 & .\build.bat Release
 if($LASTEXITCODE -ne 0){throw "network visual BitBlt Release build failed"}
 & python -u -X utf8 .\tests\winui\test_network_visual_gui.py --configuration Release --capture before
 if($LASTEXITCODE -ne 0){throw "network visual BitBlt GUI failed"}
 $source=Join-Path $temp "logs\network-visual\network-visual-before.png"
 if(-not (Test-Path -LiteralPath $source -PathType Leaf)){throw "network visual BitBlt before screenshot missing"}
 $dest=Join-Path $repo "logs\remote-evidence\network-visual-before.png"
 Copy-Item -LiteralPath $source -Destination $dest -Force
 Write-Host "NETWORK_VISUAL_BITBLT_BEFORE=PASS"
 Write-Host "NETWORK_VISUAL_BEFORE_FILE=network-visual-before.png"
}finally{
 Set-Location -LiteralPath $repo
 if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
 & git worktree prune
}
